gQ8(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0628\u064a\u0627\u0646\u0627\u062a \u0644\u0647\u0630\u0647 \u0627\u0644\u0641\u062a\u0631\u0629"},
gCs(){return"\u0627\u0644\u0633\u0627\u0628\u0642"},
gQ9(){return"\u0627\u0644\u0625\u062c\u0645\u0627\u0644\u064a"},
