gQb(){return"\u0627\u0644\u0645\u0633\u0627\u0641\u0629"},
gCu(){return"\u0645\u0639\u062f\u0644 \u0636\u0631\u0628\u0627\u062a \u0627\u0644\u0642\u0644\u0628"},
gQc(){return"\u062a\u0642\u0644\u0628 \u0645\u0639\u062f\u0644 \u0636\u0631\u0628\u0627\u062a \u0627\u0644\u0642\u0644\u0628"},
