gCw(){return"\u0645\u0639\u062f\u0644 \u0627\u0644\u062a\u0646\u0641\u0633"},
gCx(){return"\u062a\u0634\u0628\u0639 \u0627\u0644\u0623\u0643\u0633\u062c\u064a\u0646 \u0641\u064a \u0627\u0644\u062f\u0645"},
