gQg(){return"\u0636\u063a\u0637 \u0627\u0644\u062f\u0645 (\u0627\u0644\u0627\u0646\u0642\u0628\u0627\u0636\u064a)"},
gQh(){return"\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062c\u0633\u0645"},
gCy(){return"\u0627\u0644\u0648\u0632\u0646"},
gCC(){return"\u0627\u0644\u062a\u0645\u0627\u0631\u064a\u0646"},
