gf4(){return"--"},
gQQ(){return"\u064a\u0644\u0632\u0645 \u0625\u0630\u0646 \u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0644\u0644\u0628\u062d\u062b \u0639\u0646 \u0627\u0644\u0633\u0648\u0627\u0631. \u0627\u0633\u0645\u062d \u0628\u0647 \u0644\u0647\u0630\u0627 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0647\u0627\u062a\u0641 \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
gQR(){return"\u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0645\u062a\u0648\u0642\u0641. \u0634\u063a\u0651\u0644 \u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0641\u064a \u0647\u0627\u062a\u0641\u0643 \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
gQS(){return"\u0647\u0630\u0627 \u0627\u0644\u062c\u0647\u0627\u0632 \u0644\u0627 \u064a\u062f\u0639\u0645 \u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0645\u0646\u062e\u0641\u0636 \u0627\u0644\u0637\u0627\u0642\u0629 \u0627\u0644\u0630\u064a \u064a\u0633\u062a\u062e\u062f\u0645\u0647 \u0627\u0644\u0633\u0648\u0627\u0631."},
gCN(){return"\u0627\u0644\u0625\u0642\u0631\u0627\u0646 \u0628\u0627\u0644\u0639\u0646\u0648\u0627\u0646"},
gQT(){return"\u0623\u062f\u062e\u0644 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0645\u0637\u0628\u0648\u0639 \u0623\u0633\u0641\u0644 \u0631\u0645\u0632 QR \u0639\u0644\u0649 \u0627\u0644\u0639\u0644\u0628\u0629 \u0623\u0648 \u0639\u0644\u0649 \u0638\u0647\u0631 \u0627\u0644\u0633\u0648\u0627\u0631."},
gQU(){return"\u064a\u062a\u0643\u0648\u0646 \u0627\u0644\u0639\u0646\u0648\u0627\u0646 \u0645\u0646 12 \u062d\u0631\u0641\u064b\u0627\u060c \u0645\u062b\u0644 A1:B2:C3:D4:E5:F6"},
gQV(){return"\u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u062c\u0647\u0627\u0632"},
gQW(){return"\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0633\u0648\u0627\u0631 \u0628\u0647\u0630\u0627 \u0627\u0644\u0639\u0646\u0648\u0627\u0646."},
