gQY(){return"\u0627\u0644\u0623\u0633\u0627\u0648\u0631 \u0627\u0644\u062a\u064a \u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u064a\u0647\u0627"},
gQZ(){return"\u0644\u0645 \u064a\u062a\u0645 \u0627\u0644\u0639\u062b\u0648\u0631 \u0639\u0644\u0649 \u0633\u0648\u0627\u0631. \u062a\u0623\u0643\u062f \u0645\u0646 \u0634\u062d\u0646\u0647 \u0648\u0642\u0631\u0628\u0647 \u062b\u0645 \u062d\u0627\u0648\u0644 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649."},
gR_(){return"\u0627\u0634\u062d\u0646 \u0627\u0644\u0633\u0648\u0627\u0631 \u0648\u0623\u0628\u0642\u0647 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0647\u0627\u062a\u0641\u0643. \u064a\u062c\u0628 \u0623\u0646 \u064a\u0643\u0648\u0646 \u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0645\u0641\u0639\u0651\u0644\u064b\u0627."},
gCP(){return"\u0645\u0633\u062d \u0631\u0645\u0632 QR"},
gR0(){return"\u0636\u0639 \u0631\u0645\u0632 QR \u0627\u0644\u0645\u0648\u062c\u0648\u062f \u0639\u0644\u0649 \u0627\u0644\u0639\u0644\u0628\u0629 \u0623\u0648 \u062e\u0644\u0641 \u0627\u0644\u0633\u0648\u0627\u0631 \u062f\u0627\u062e\u0644 \u0627\u0644\u0625\u0637\u0627\u0631."},
gR1(){return"\u0644\u0627 \u064a\u062d\u062a\u0648\u064a \u0631\u0645\u0632 QR \u0647\u0630\u0627 \u0639\u0644\u0649 \u0639\u0646\u0648\u0627\u0646 \u0633\u0648\u0627\u0631."},
