R4(a){return"\u0627\u0644\u0625\u0634\u0627\u0631\u0629 "+a},
gR5(){return"\u0627\u0631\u0628\u0637 \u0633\u0648\u0627\u0631\u0643 \u0644\u062a\u0635\u0644 \u0642\u064a\u0627\u0633\u0627\u062a\u0643 \u0625\u0644\u0649 \u0647\u0627\u062a\u0641\u0643."},
gR6(){return"\u0625\u0642\u0631\u0627\u0646 \u0627\u0644\u0633\u0648\u0627\u0631"},
gRb(){return"\u064a\u0648\u0645"},
gCS(){return"\u0634\u0647\u0631"},
gCT(){return"\u0623\u0633\u0628\u0648\u0639"},
gCU(){return"\u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629"},
gRn(){return"\u064a\u064f\u0633\u062c\u064e\u0651\u0644 \u0643\u0644 \u0648\u0635\u0648\u0644 \u0625\u0644\u0649 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0641\u064a \u0627\u0644\u0628\u0648\u0627\u0628\u0629\u060c \u0628\u0645\u0627 \u0641\u064a \u0630\u0644\u0643 \u0627\u0644\u0645\u062d\u0627\u0648\u0644\u0627\u062a \u0627\u0644\u0645\u0631\u0641\u0648\u0636\u0629. \u064a\u0645\u0643\u0646\u0643 \u0623\u0646 \u062a\u0631\u0649 \u0641\u064a \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0645\u0646 \u0627\u0637\u0644\u0639 \u0648\u0645\u062a\u0649."},
gRo(){return"\u0633\u062c\u0644 \u0627\u0644\u0648\u0635\u0648\u0644"},
gRp(){return"\u0633\u064a\u0638\u0647\u0631 \u0647\u0646\u0627 \u0642\u0628\u0644 \u0627\u0644\u0646\u0634\u0631 \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0639\u0646\u0648\u0627\u0646\u0647 \u0648\u0637\u0631\u064a\u0642\u0629 \u062a\u0642\u062f\u064a\u0645 \u0627\u0644\u0637\u0644\u0628. \u064a\u0645\u0643\u0646\u0643 \u0623\u064a\u0636\u064b\u0627 \u0645\u0631\u0627\u0633\u0644\u062a\u0646\u0627 \u0645\u0646 \u0627\u0644\u062a\u0637\u0628\u064a\u0642 \u0639\u0628\u0631 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u0634\u062e\u0635\u064a > \u0627\u0644\u0645\u0644\u0627\u062d\u0638\u0627\u062a."},
gRq(){return"\u0627\u0644\u062a\u0648\u0627\u0635\u0644"},
gRr(){return"\u0645\u0627 \u064a\u0642\u064a\u0633\u0647 \u0627\u0644\u0633\u0648\u0627\u0631: \u0646\u0628\u0636 \u0627\u0644\u0642\u0644\u0628 \u0648\u062a\u0642\u0644\u0628\u0647 (HRV) \u0648\u0623\u0643\u0633\u062c\u064a\u0646 \u0627\u0644\u062f\u0645 (SpO2) \u0648\u062a\u062e\u0637\u064a\u0637 \u0627\u0644\u0642\u0644\u0628 \u0648\u0627\u0644\u0646\u0648\u0645 \u0648\u0627\u0644\u062e\u0637\u0648\u0627\u062a \u0648\u0627\u0644\u062a\u0645\u0627\u0631\u064a\u0646 \u0648\u062d\u0631\u0627\u0631\u0629 \u0627\u0644\u062c\u0633\u0645 \u0648\u0627\u0644\u062a\u0648\u062a\u0631 \u0648\u0636\u063a\u0637 \u0627\u0644\u062f\u0645 \u0627\u0644\u062a\u0642\u062f\u064a\u0631\u064a. \u0645\u0627 \u062a\u062f\u062e\u0644\u0647 \u0623\u0646\u062a: \u0627\u0644\u0639\u0645\u0631 \u0648\u0627\u0644\u0637\u0648\u0644 \u0648\u0627\u0644\u0648\u0632\u0646 \u0648\u0627\u0644\u062c\u0646\u0633 \u0648\u062a\u0643\u0648\u064a\u0646 \u0627\u0644\u062c\u0633\u0645 \u0648\u0627\u0644\u062a\u0630\u0643\u064a\u0631\u0627\u062a. \u0639\u0646\u0648\u0627\u0646 \u0627\u0644\u0628\u0644\u0648\u062a\u0648\u062b \u0644\u0644\u0633\u0648\u0627\u0631. \u0644\u0627 \u0646\u0637\u0644\u0628 \u0627\u0633\u0645\u0643 \u0623\u0648 \u0631\u0642\u0645 \u0647\u0648\u064a\u062a\u0643 \u0623\u0648 \u0647\u0627\u062a\u0641\u0643 \u0623\u0648 \u0628\u0631\u064a\u062f\u0643 \u0627\u0644\u0625\u0644\u0643\u062a\u0631\u0648\u0646\u064a\u061b \u062a\u064f\u0639\u0631\u0641 \u0641\u064a \u0627\u0644\u0628\u0648\u0627\u0628\u0629 \u0628\u0627\u0633\u0645 \u0645\u0633\u062a\u0639\u0627\u0631 \u0639\u0634\u0648\u0627\u0626\u064a \u0641\u0642\u0637."},
gRs(){return"\u0645\u0627 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u062a\u064a \u0646\u0639\u0627\u0644\u062c\u0647\u0627\u061f"},
gRt(){return"\u0645\u0633\u0648\u062f\u0629: \u0644\u0645 \u062a\u062a\u0645 \u0645\u0631\u0627\u062c\u0639\u0629 \u0647\u0630\u0627 \u0627\u0644\u0646\u0635 \u0642\u0627\u0646\u0648\u0646\u064a\u064b\u0627. \u0633\u064a\u064f\u0636\u0627\u0641 \u0627\u0633\u0645 \u0627\u0644\u0645\u0633\u0624\u0648\u0644 \u0639\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0648\u0639\u0646\u0648\u0627\u0646\u0647 \u0648\u0645\u062f\u062f \u0627\u0644\u0627\u062d\u062a\u0641\u0627\u0638 \u0642\u0628\u0644 \u0627\u0644\u0646\u0634\u0631."},
gRu(){return"\u064a\u0648\u0636\u062d \u0647\u0630\u0627 \u0627\u0644\u0646\u0635 \u0643\u064a\u0641 \u064a\u0639\u0627\u0644\u062c \u062a\u0637\u0628\u064a\u0642 Bileklik \u0648\u0628\u0648\u0627\u0628\u062a\u0647 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0648\u0641\u0642 \u0642\u0627\u0646\u0648\u0646 \u062d\u0645\u0627\u064a\u0629 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u062a\u0631\u0643\u064a \u0631\u0642\u0645 6698 (KVKK)."},
gRv(){return"\u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0635\u062d\u064a\u0629 \u0641\u0626\u0629 \u062e\u0627\u0635\u0629 \u0645\u0646 \u0627\u0644\u0628\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0634\u062e\u0635\u064a\u0629 \u0648\u062a\u064f\u0639\u0627\u0644\u062c \u0628\u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0627\u0644\u0635\u0631\u064a\u062d\u0629 (\u0627\u0644\u0645\u0627\u062f\u0629 6 \u0645\u0646 KVKK). \u0643\u0644 \u0645\u0634\u0627\u0631\u0643\u0629 \u062a\u062d\u062a\u0627\u062c \u0625\u0644\u0649 \u0645\u0648\u0627\u0641\u0642\u0629 \u0645\u0633\u062a\u0642\u0644\u0629: \u062a\u062e\u062a\u0627\u0631 \u0645\u0646 \u064a\u0631\u0649 \u0623\u064a \u0627\u0644\u0623\u0646\u0648\u0627\u0639 \u0648\u0644\u0623\u064a \u0645\u062f\u0629\u060c \u0648\u064a\u0645\u0643\u0646\u0643 \u0633\u062d\u0628 \u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0641\u064a \u0623\u064a \u0648\u0642\u062a."},
gRw(){return"\u0627\u0644\u0623\u0633\u0627\u0633 \u0627\u0644\u0642\u0627\u0646\u0648\u0646\u064a"},
gRx(){return"\u0644\u0639\u0631\u0636 \u0642\u064a\u0627\u0633\u0627\u062a\u0643 \u0639\u0644\u064a\u0643\u060c \u0648\u0645\u0634\u0627\u0631\u0643\u062a\u0647\u0627 \u0645\u0639 \u0627\u0644\u0623\u0637\u0628\u0627\u0621 \u0648\u0645\u0624\u0633\u0633\u0627\u062a \u0627\u0644\u0628\u062d\u062b \u0648\u0623\u0641\u0631\u0627\u062f \u0627\u0644\u0639\u0627\u0626\u0644\u0629 \u0627\u0644\u0630\u064a\u0646 \u062a\u062e\u062a\u0627\u0631\u0647\u0645\u060c \u0648\u0643\u062a\u0627\u0628\u062a\u0647\u0627 \u0641\u064a Apple Health \u0623\u0648 Health Connect \u0625\u0646 \u0631\u063a\u0628\u062a. \u0644\u0627 \u062a\u064f\u0633\u062a\u062e\u062f\u0645 \u0628\u064a\u0627\u0646\u0627\u062a\u0643 \u0644\u0644\u0625\u0639\u0644\u0627\u0646\u0627\u062a \u0648\u0644\u0627 \u062a\u064f\u0628\u0627\u0639."},
gRy(){return"\u0644\u0645\u0627\u0630\u0627 \u0646\u0639\u0627\u0644\u062c\u0647\u0627\u061f"},
